package com.testforge.testforge_backend.testsuite.service;
import com.fasterxml.jackson.databind.ObjectMapper; import com.testforge.testforge_backend.automation.dto.GeneratedScriptResponse; import com.testforge.testforge_backend.testsuite.dto.SuiteJUnitConfiguration; import org.springframework.stereotype.Component; import java.nio.charset.StandardCharsets; import java.util.Base64;
@Component public class JUnitSuiteSourceTransformer {private final ObjectMapper json=new ObjectMapper();
 public GeneratedScriptResponse apply(GeneratedScriptResponse generated,SuiteJUnitConfiguration config){String source=generated.source();for(String tag:config.tags())source=source.replace("public class ","@org.junit.jupiter.api.Tag(\""+tag+"\")\npublic class ");if(config.lifecycleEnabled()){source=source.replace("public class ","public class ").replaceFirst("\\{\\s*\\n", "{\n\n    @org.junit.jupiter.api.BeforeAll static void testForgeBeforeAll() { System.out.println(\"[TestForge] Suite lifecycle started\"); }\n    @org.junit.jupiter.api.BeforeEach void testForgeBeforeEach() { System.out.println(\"[TestForge] Test isolation started\"); }\n    @org.junit.jupiter.api.AfterEach void testForgeAfterEach() { System.out.println(\"[TestForge] Test isolation completed\"); }\n    @org.junit.jupiter.api.AfterAll static void testForgeAfterAll() { System.out.println(\"[TestForge] Suite lifecycle completed\"); }\n");}
  if(!config.parameterSets().isEmpty()){try{String encoded=Base64.getEncoder().encodeToString(json.writeValueAsBytes(config.parameterSets()));source=source.replace("import org.junit.jupiter.api.Test;","import org.junit.jupiter.params.ParameterizedTest;\nimport org.junit.jupiter.params.provider.Arguments;\nimport org.junit.jupiter.params.provider.MethodSource;\nimport java.util.stream.Stream;");source=source.replace("    @Test\n    void execute() throws Exception {","    @ParameterizedTest\n    @MethodSource(\"testForgeParameters\")\n    void execute(Map<String, String> parameters) throws Exception {");source=source.replace("Map<String, String> runtimeData = new HashMap<>();","Map<String, String> runtimeData = new HashMap<>(parameters);");int end=source.lastIndexOf('}');String provider="\n    static Stream<Arguments> testForgeParameters() throws Exception {\n        byte[] value = Base64.getDecoder().decode(\""+encoded+"\");\n        JsonNode rows = new ObjectMapper().readTree(new String(value, StandardCharsets.UTF_8));\n        java.util.List<Arguments> arguments = new java.util.ArrayList<>();\n        for (JsonNode row : rows) {\n            Map<String, String> values = new ObjectMapper().convertValue(row, new com.fasterxml.jackson.core.type.TypeReference<Map<String, String>>() {});\n            arguments.add(Arguments.of(values));\n        }\n        return arguments.stream();\n    }\n";source=source.substring(0,end)+provider+source.substring(end);}catch(Exception e){throw new IllegalArgumentException("JUnit parameter sets could not be generated.");}}
  return new GeneratedScriptResponse(generated.automationScriptId(),generated.automationScriptBusinessId(),generated.testCaseId(),generated.className(),generated.language(),generated.framework(),source,generated.generatedStepCount(),generated.generatedAt(),generated.stale());}
}
